"""This module provides the implementation to get the uplane_trace trace pcap file with help of
the command "get_log_file"
"""
import os


class ClassicalGnbUplaneTraceLogFileProvider:
    """Class to get the trace file for the uplane_trace trace. Currently the pcap files are returned
    """

    def get_uplane_trace_log_file(self, log_directory, collector_config):
        """Determine the uplane_trace trace location and return it.

        :param str log_directory: the path where the log files of the collector are stored
        :param str collector_config: the collector configuration of the collector to obtain additional information
        """
        tcpdump_path = os.path.join(log_directory, collector_config['collector'])
        log_files = [os.path.join(tcpdump_path, filename) for filename in os.listdir(tcpdump_path)]
        return log_files
